     e=mkRaider(p.x+80,p.y); e.elite=1; e.wep=sample; e.dmg=sample.dmg; e.noGunDrop=null; e.paidRevive=0; e.bag=[];
     k='gun_'+sample.id; el=sample.el; g.ents=[e];
